package foodchain

import (
	"fmt"
	"strings"
)

var animals = []string{"fly", "spider", "bird", "cat", "dog", "goat", "cow", "horse"}

var comments = []string{
	"I don't know why she swallowed the fly. Perhaps she'll die.",
	"It wriggled and jiggled and tickled inside her.",
	"How absurd to swallow a bird!",
	"Imagine that, to swallow a cat!",
	"What a hog, to swallow a dog!",
	"Just opened her throat and swallowed a goat!",
	"I don't know how she swallowed a cow!",
	"She's dead, of course!",
}

// Verse returns the lyrics of verse v (1-based).
func Verse(v int) string {
	var b strings.Builder
	fmt.Fprintf(&b, "I know an old lady who swallowed a %s.\n", animals[v-1])
	fmt.Fprintf(&b, "%s\n", comments[v-1])
	for i := v - 1; i > 0; i-- {
		next := animals[i-1]
		if next == "spider" {
			next += " that wriggled and jiggled and tickled inside her"
		}
		fmt.Fprintf(&b, "She swallowed the %s to catch the %s.\n", animals[i], next)
	}
	return strings.TrimSuffix(b.String(), "\n")
}

// Verses returns the lyrics of verses start through end, joined with a blank line.
func Verses(start, end int) string {
	return strings.Join(verses(start, end), "\n\n")
}

// Song returns the complete song.
func Song() string {
	return Verses(1, len(animals))
}

func verses(start, end int) []string {
	out := make([]string, 0, end-start+1)
	for v := start; v <= end; v++ {
		out = append(out, Verse(v))
	}
	return out
}

